import sys

def main():
    data = sys.stdin.read().split()
    c0_10 = c11_20 = c21_30 = c31_up = 0
    for token in data:
        n = int(token)
        if n < 0:
            break
        if n <= 10:
            c0_10 += 1
        elif n <= 20:
            c11_20 += 1
        elif n <= 30:
            c21_30 += 1
        else:
            c31_up += 1
    print(f"{c0_10} {c11_20} {c21_30} {c31_up}")

if __name__ == "__main__":
    main()
